  /// `EEEffect3D::mBoundingRadius` and `EEEffect2D::mBoundingRadius` (saved)
  float bounding_radius;
  /// `EEEffect2D::mPosition` (saved)
  EeGe3DPoint position;
  /// `EEE3DSmokeGenerator`'s
